// The C# arm of the generator family. Reads guest sources for [KayaGen]
// declarations and writes <Type>Kaya.cs beside them; the DECLARATION'S
// SHAPE decides what comes out. Generated files are checked in;
// tools/gen-guests.py regenerates and diffs.
//
//     dotnet run --project tools/kaya-csgen -- <guest source dir>

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

static class Program
{
    static int Main(string[] args)
    {
        if (args.Length != 1)
        {
            Console.Error.WriteLine("usage: kaya-csgen <guest source dir>");
            return 2;
        }
        var dir = args[0];
        var sums = 0;
        foreach (var file in Directory.EnumerateFiles(dir, "*.cs").OrderBy(f => f))
        {
            if (Path.GetFileName(file).EndsWith("Kaya.cs", StringComparison.Ordinal))
                continue;
            var root = CSharpSyntaxTree.ParseText(File.ReadAllText(file)).GetRoot();
            var records = root.DescendantNodes()
                .OfType<RecordDeclarationSyntax>()
                .ToList();
            foreach (var marked in records.Where(IsKayaGen))
            {
                var name = marked.Identifier.Text;
                var ns = marked.Ancestors()
                    .OfType<BaseNamespaceDeclarationSyntax>()
                    .Select(n => n.Name.ToString())
                    .FirstOrDefault();
                var outPath = Path.Combine(dir, name + "Kaya.cs");
                // The declaration's shape decides: abstract record =
                // sum, plain record = record.
                if (marked.Modifiers.Any(m => m.IsKind(SyntaxKind.AbstractKeyword)))
                {
                    // Declaration order in the file is the constructor
                    // order — the same order every other tier stamps.
                    var ctors = records
                        .Where(r => r.BaseList != null && r.BaseList.Types.Any(t =>
                            t.Type is IdentifierNameSyntax id && id.Identifier.Text == name))
                        .OrderBy(r => r.SpanStart)
                        .Select(r => (name: r.Identifier.Text,
                            fields: (r.ParameterList?.Parameters ?? default)
                                .Select(p => (name: p.Identifier.Text, type: p.Type?.ToString()))
                                .Where(f => Wire.Contains(f.type))
                                .ToList()))
                        .ToList();
                    if (ctors.Count < 2)
                    {
                        Console.Error.WriteLine(
                            $"kaya-csgen: [KayaGen] {name} needs two derived records or more");
                        return 1;
                    }
                    WriteIfChanged(outPath, GenerateSum(ns, name, ctors));
                    Console.WriteLine(
                        $"kaya-csgen: wrote {outPath} ({ctors.Count} constructors of {name})");
                }
                else
                {
                    // The wire fields: primary-constructor parameters
                    // of wire type, in declaration order.
                    var fields = (marked.ParameterList?.Parameters ?? default)
                        .Select(p => (name: p.Identifier.Text, type: p.Type?.ToString()))
                        .Where(f => Wire.Contains(f.type))
                        .ToList();
                    if (fields.Count == 0)
                    {
                        Console.Error.WriteLine(
                            $"kaya-csgen: [KayaGen] {name} has no wire-typed parameters");
                        return 1;
                    }
                    WriteIfChanged(outPath, GenerateRecord(ns, name, fields));
                    Console.WriteLine(
                        $"kaya-csgen: wrote {outPath} ({fields.Count} fields of {name})");
                }
                sums++;
            }
        }
        if (sums == 0)
            Console.Error.WriteLine($"kaya-csgen: no [KayaGen] records under {dir}");
        return 0;
    }

    // The wire vocabulary a parameter type maps into. byte[] is the blob
    // channel, and KayaRecords.Info maps byte[] parameters in, so a
    // skipped one HERE shifts every later exact-index token off the
    // runtime schema.
    static readonly System.Collections.Generic.HashSet<string> Wire =
        new() { "string", "bool", "long", "double", "byte[]" };

    static bool IsKayaGen(RecordDeclarationSyntax r) =>
        r.AttributeLists.SelectMany(l => l.Attributes)
            .Any(a => a.Name.ToString() is "KayaGen" or "KayaGenAttribute");

    static string GenerateSum(string ns, string sum,
        List<(string name, List<(string name, string type)> fields)> ctors)
    {
        var b = new System.Text.StringBuilder();
        b.AppendLine("// Code generated by kaya-csgen; DO NOT EDIT.");
        b.AppendLine("// Regenerate with tools/gen-guests.py (which also checks freshness).");
        b.AppendLine();
        if (ns != null)
        {
            b.AppendLine($"namespace {ns};");
            b.AppendLine();
        }
        b.AppendLine($"/// <summary>{sum}'s generated sum surface: the collection factory");
        b.AppendLine("/// and the compile-total eliminator — one required delegate per");
        b.AppendLine("/// constructor, named at the call site, with the scene checking");
        b.AppendLine("/// totality again.</summary>");
        b.AppendLine($"static class {sum}Kaya");
        b.AppendLine("{");
        var typeofs = string.Join(", ", ctors.Select(c => $"typeof({c.name})"));
        b.AppendLine($"    public static SumCollection<{sum}> Collection(Tx tx) =>");
        b.AppendLine($"        tx.SumOf<{sum}>({typeofs});");
        b.AppendLine();
        b.AppendLine($"    public static Widget EachSum(Tx tx, SumCollection<{sum}> c,");
        for (var i = 0; i < ctors.Count; i++)
        {
            var comma = i == ctors.Count - 1 ? ") =>" : ",";
            b.AppendLine(
                $"        System.Action<Tpl, SumCase<{ctors[i].name}>> {Lower(ctors[i].name)}{comma}");
        }
        var arms = string.Join(", ", ctors.Select(c => $"c.Arm<{c.name}>({Lower(c.name)})"));
        b.AppendLine($"        tx.EachSum(c, {arms});");
        b.AppendLine();
        foreach (var ctor in ctors.Where(c => c.fields.Count > 0))
        {
            b.AppendLine($"    /// <summary>As{ctor.name} re-eliminates at call time: the null");
            b.AppendLine("    /// is the refinement, fresh at write time — a stale occurrence");
            b.AppendLine($"    /// folds into ?. — and each setter's update carries {ctor.name}");
            b.AppendLine("    /// as its witness, asserted again by the scene.</summary>");
            b.AppendLine($"    public static {sum}{ctor.name}Patch As{ctor.name}(Tx tx, SumCollection<{sum}> c, object key) =>");
            b.AppendLine($"        tx != null && c.Get(tx, key) is {ctor.name}");
            b.AppendLine($"            ? new {sum}{ctor.name}Patch(tx, c, key) : null;");
            b.AppendLine();
        }
        b.AppendLine("}");
        foreach (var ctor in ctors.Where(c => c.fields.Count > 0))
        {
            b.AppendLine();
            b.AppendLine($"/// <summary>{ctor.name}'s refined patch: named setters over the");
            b.AppendLine("/// witnessed update.</summary>");
            b.AppendLine($"sealed class {sum}{ctor.name}Patch");
            b.AppendLine("{");
            b.AppendLine("    readonly Tx tx;");
            b.AppendLine($"    readonly SumCollection<{sum}> c;");
            b.AppendLine("    readonly object key;");
            b.AppendLine();
            b.AppendLine($"    internal {sum}{ctor.name}Patch(Tx tx, SumCollection<{sum}> c, object key)");
            b.AppendLine("    {");
            b.AppendLine("        this.tx = tx;");
            b.AppendLine("        this.c = c;");
            b.AppendLine("        this.key = key;");
            b.AppendLine("    }");
            foreach (var f in ctor.fields)
            {
                b.AppendLine();
                b.AppendLine($"    public {sum}{ctor.name}Patch {f.name}({f.type} v)");
                b.AppendLine("    {");
                b.AppendLine($"        c.UpdateField<{ctor.name}, {f.type}>(tx, key, x => x.{f.name}, v);");
                b.AppendLine("        return this;");
                b.AppendLine("    }");
            }
            b.AppendLine("}");
        }
        return b.ToString();
    }

    static string GenerateRecord(string ns, string rec, List<(string name, string type)> fields)
    {
        var b = new System.Text.StringBuilder();
        b.AppendLine("// Code generated by kaya-csgen; DO NOT EDIT.");
        b.AppendLine("// Regenerate with tools/gen-guests.py (which also checks freshness).");
        b.AppendLine();
        if (ns != null)
        {
            b.AppendLine($"namespace {ns};");
            b.AppendLine();
        }
        b.AppendLine($"/// <summary>{rec}'s generated record surface: the collection");
        b.AppendLine("/// factory, exact-index field tokens, and a named-setter patch");
        b.AppendLine("/// (each set records one update_field — a patch is recorded");
        b.AppendLine("/// writes, never a diff).</summary>");
        b.AppendLine($"static class {rec}Kaya");
        b.AppendLine("{");
        b.AppendLine($"    public static RecordCollection<{rec}> Collection(Tx tx) =>");
        b.AppendLine($"        tx.CollectionOf<{rec}>();");
        b.AppendLine();
        for (var i = 0; i < fields.Count; i++)
        {
            b.AppendLine(
                $"    public static readonly Field<{fields[i].type}> {fields[i].name} ="
                + $" KayaRecords.FieldAt<{fields[i].type}>({i});");
        }
        b.AppendLine();
        b.AppendLine($"    public static {rec}KayaPatch Patch(Tx tx, RecordCollection<{rec}> c, object key) =>");
        b.AppendLine($"        new {rec}KayaPatch(c.Patch(tx, key));");
        b.AppendLine();
        b.AppendLine("    /// <summary>The record template, expression form: the body runs");
        b.AppendLine("    /// once, authoring the blueprint with the typed row surface");
        b.AppendLine("    /// (exact-index tokens, no probes); stamping is the core's");
        b.AppendLine("    /// replay.</summary>");
        b.AppendLine($"    public static Widget Each(Tx tx, RecordCollection<{rec}> c,");
        b.AppendLine($"        System.Action<{rec}Row> body) =>");
        b.AppendLine($"        tx.Each(c.Collection, t => body(new {rec}Row(t)));");
        b.AppendLine();
        b.AppendLine("    /// <summary>The same, for a For opened INSIDE a template body —");
        b.AppendLine("    /// the nested table's shape, \"for every account, a positions");
        b.AppendLine("    /// table\". Without it the nested body holds the raw Tpl and");
        b.AppendLine("    /// spells its cells with the static tokens rather than the row's");
        b.AppendLine("    /// own (docs/deferred.md, the closed C# façade entry).</summary>");
        b.AppendLine($"    public static Node Each(Tpl t, RecordCollection<{rec}> c,");
        b.AppendLine($"        System.Action<{rec}Row> body) =>");
        b.AppendLine($"        t.Each(c.Collection, inner => body(new {rec}Row(inner)));");
        b.AppendLine();
        b.AppendLine("    /// <summary>The foreach form: `foreach (var row in todos.Rows())`");
        b.AppendLine("    /// traces the record template — the body runs once, and the");
        b.AppendLine("    /// enumerator's Dispose closes the template, so foreach makes the");
        b.AppendLine("    /// close structural, even on break.</summary>");
        b.AppendLine($"    public static {rec}RowSeq Rows(this RecordCollection<{rec}> c) =>");
        b.AppendLine($"        new {rec}RowSeq(c);");
        b.AppendLine("}");
        b.AppendLine();
        b.AppendLine("/// <summary>The row surface: the template handle plus one token per");
        b.AppendLine("/// wire field, and the template zone's whole vocabulary aimed at them.");
        b.AppendLine("///");
        b.AppendLine("/// The forwarders below are the ZONE and not a selection from it. A");
        b.AppendLine("/// constructor Tpl has and this does not is reachable through tx.Each");
        b.AppendLine("/// and not through `foreach (var row in c.Rows())`, which is a");
        b.AppendLine("/// difference no guest should have to know about, and the shape this");
        b.AppendLine("/// list drifts into: it named five constructors by hand while the");
        b.AppendLine("/// zone named six, and the scene that wanted a per-row entry could");
        b.AppendLine("/// not use either, so it opened the For itself and reached for the");
        b.AppendLine("/// widget-kind floor (docs/sugar-pass-plan.md S4b).");
        b.AppendLine("/// Add here whatever is added to Tpl: the prop setters below are");
        b.AppendLine("/// forwarded for the same reason the constructors are.");
        b.AppendLine("/// The zone's PLUMBING — Widget, the Bind*Field setters, AddChild —");
        b.AppendLine("/// stays off deliberately: a row surface hands out sugar, and its");
        b.AppendLine("/// Tpl is private so the floor is reached by opening the For");
        b.AppendLine("/// yourself. THE NESTED-FOR VOCABULARY IS NOT PLUMBING and is");
        b.AppendLine("/// forwarded — Collection, Each, ForEach, and the Columns that");
        b.AppendLine("/// names the Node Each hands back — or a nested table is spellable");
        b.AppendLine("/// through tx.Each and not through a row at all. When and");
        b.AppendLine("/// ContextMenu are the two still off the list; Java's RowSurface");
        b.AppendLine("/// forwards both, and that divergence is recorded in");
        b.AppendLine("/// docs/deferred.md rather than blessed here.</summary>");
        b.AppendLine($"sealed class {rec}Row");
        b.AppendLine("{");
        b.AppendLine("    readonly Tpl t;");
        foreach (var f in fields)
        {
            b.AppendLine($"    public readonly Field<{f.type}> {f.name} = {rec}Kaya.{f.name};");
        }
        b.AppendLine();
        b.AppendLine($"    internal {rec}Row(Tpl t) => this.t = t;");
        b.AppendLine();
        // The handler delegates, spelled once. A TEMPLATE handler carries
        // the stamped copy's key path; forwarding the LIVE zone's shape
        // here would hand a guest a handler that cannot say which copy
        // fired.
        const string keys = "System.Collections.Generic.List<object>";
        var onText = $"System.Action<Tx, {keys}, string>";
        var onToggle = $"System.Action<Tx, {keys}, bool>";
        var onValue = $"System.Action<Tx, {keys}, double>";
        var onSelect = $"System.Action<Tx, {keys}, int>";

        // One forwarder, wrapped the way the hand-written Tpl wraps: a
        // trailing handler parameter goes on its own line rather than
        // running past the margin.
        void Fwd(string name, string[] pars, string args) =>
            FwdAs("Node", name, pars, args);

        // The same forwarder for a zone method that hands back something
        // other than a Node: the return type is the only difference.
        void FwdAs(string ret, string name, string[] pars, string args)
        {
            var one = $"    public {ret} {name}({string.Join(", ", pars)}) => t.{name}({args});";
            if (one.Length <= 84)
            {
                b.AppendLine(one);
            }
            else
            {
                // The handler is the parameter that overflows, so it is
                // the one that moves; a lone handler leaves the open
                // paren by itself rather than a dangling comma.
                var head = string.Join(", ", pars[..^1]);
                b.AppendLine($"    public {ret} {name}({head}{(head.Length > 0 ? "," : "")}");
                b.AppendLine($"        {pars[^1]}) =>");
                b.AppendLine($"        t.{name}({args});");
            }
            b.AppendLine();
        }

        // A PROP SETTER forwards the same way but returns nothing, and
        // it is the BODY that overflows rather than a parameter (the
        // name is spelled twice), so the wrap is the hand-written Tpl's:
        // the signature keeps its parameters and the call moves down.
        void Set(string name, string[] pars, string args)
        {
            var one = $"    public void {name}({string.Join(", ", pars)}) => t.{name}({args});";
            if (one.Length <= 84)
            {
                b.AppendLine(one);
            }
            else
            {
                b.AppendLine($"    public void {name}({string.Join(", ", pars)}) =>");
                b.AppendLine($"        t.{name}({args});");
            }
            b.AppendLine();
        }

        Fwd("Label", ["string text"], "text");
        Fwd("Label", ["Signal s"], "s");
        Fwd("Label", ["Field<string> f"], "f");
        Fwd("Heading", ["string text"], "text");
        Fwd("Heading", ["Signal s"], "s");
        Fwd("Heading", ["Field<string> f"], "f");
        Fwd("Caption", ["string text"], "text");
        Fwd("Caption", ["Signal s"], "s");
        Fwd("Caption", ["Field<string> f"], "f");
        Fwd("Button", ["string text"], "text");
        Fwd("Button", ["Signal s"], "s");
        Fwd("Button", ["Field<string> f"], "f");
        Fwd("Image", ["byte[] source"], "source");
        Fwd("Image", ["Signal s"], "s");
        Fwd("Image", ["Field<byte[]> f"], "f");
        Fwd("Canvas", ["Viewbox vb", "System.Action<Draw> body"], "vb, body");
        Fwd("Checkbox", ["Field<bool> f", $"{onToggle} onToggle = null"], "f, onToggle");
        Fwd("Entry", [$"{onText} onChange = null"], "onChange");
        Fwd("Entry", ["string text", $"{onText} onChange = null"], "text, onChange");
        Fwd("Entry", ["Signal text", $"{onText} onChange = null"], "text, onChange");
        Fwd("Entry", ["Field<string> text", $"{onText} onChange = null"], "text, onChange");
        Fwd("Textarea", [$"{onText} onChange = null"], "onChange");
        Fwd("Textarea", ["string text", $"{onText} onChange = null"], "text, onChange");
        Fwd("Textarea", ["Signal text", $"{onText} onChange = null"], "text, onChange");
        Fwd("Textarea", ["Field<string> text", $"{onText} onChange = null"], "text, onChange");
        Fwd("Progress", ["double value"], "value");
        Fwd("Progress", ["Signal value"], "value");
        Fwd("Progress", ["Field<double> value"], "value");
        Fwd("ProgressIndeterminate", [], "");
        Fwd("Slider", ["double min", "double max", "double value", $"{onValue} onChange = null"],
            "min, max, value, onChange");
        Fwd("Slider", ["double min", "double max", "Signal value", $"{onValue} onChange = null"],
            "min, max, value, onChange");
        Fwd("Slider",
            ["double min", "double max", "Field<double> value", $"{onValue} onChange = null"],
            "min, max, value, onChange");
        Fwd("Select", ["string[] options", "int selected", $"{onSelect} onSelect = null"],
            "options, selected, onSelect");
        Fwd("Select", ["string[] options", "Signal selected", $"{onSelect} onSelect = null"],
            "options, selected, onSelect");
        Fwd("Select",
            ["string[] options", "Field<double> selected", $"{onSelect} onSelect = null"],
            "options, selected, onSelect");
        Fwd("Radio", ["string[] options", "int selected", $"{onSelect} onSelect = null"],
            "options, selected, onSelect");
        Fwd("Radio", ["string[] options", "Signal selected", $"{onSelect} onSelect = null"],
            "options, selected, onSelect");
        Fwd("Radio",
            ["string[] options", "Field<double> selected", $"{onSelect} onSelect = null"],
            "options, selected, onSelect");
        Fwd("Row", ["System.Action body"], "body");
        Fwd("Column", ["System.Action body"], "body");
        Fwd("Scroll", ["System.Action body"], "body");
        Fwd("Grid", ["int columns", "System.Action body"], "columns, body");
        Fwd("Spacer", [], "");
        // THE NESTED-FOR VOCABULARY, forwarded for the reason the
        // constructors are: a row that cannot open a For cannot name the
        // Node whose header bar Columns declares, so the dashboard's
        // "a table per account" was spellable through tx.Each and not
        // through a row (docs/deferred.md). Java's RowSurface forwards
        // the same four.
        FwdAs("Collection", "Collection", [], "");
        Fwd("Each", ["Collection c", "System.Action<Tpl> body"], "c, body");
        Fwd("ForEach", ["Collection c", "System.Action<Tpl> body"], "c, body");
        Set("Columns", ["Node n", "string[] titles", "Sort sort"], "n, titles, sort");
        // THE PROP SETTERS, for the reason the constructors are here: a
        // prop reachable through tx.Each and not through `foreach (var
        // row in c.Rows())` is a difference no guest should have to know
        // about (docs/tpl-props-plan.md P1).
        Set("SetGrow", ["Node n", "double weight"], "n, weight");
        Set("SetA11yId", ["Node n", "string id"], "n, id");
        Set("SetA11yId", ["Node n", "Signal s"], "n, s");
        Set("SetA11yId", ["Node n", "Field<string> f", "uint level = 0"], "n, f, level");
        Set("SetA11yLabel", ["Node n", "string label"], "n, label");
        Set("SetA11yLabel", ["Node n", "Signal s"], "n, s");
        Set("SetA11yLabel", ["Node n", "Field<string> f", "uint level = 0"], "n, f, level");
        Set("SetA11yHint", ["Node n", "string hint"], "n, hint");
        Set("SetA11yHint", ["Node n", "Signal s"], "n, s");
        Set("SetA11yHint", ["Node n", "Field<string> f", "uint level = 0"], "n, f, level");
        Set("SetAccepts", ["Node n", "params string[] kinds"], "n, kinds");
        FwdAs("TplDragRef", "Draggable", ["Node n"], "n");
        Set("SetDropTarget", ["Node n", "params Op[] ops"], "n, ops");
        Set("SetRole", ["Node n", "Role role"], "n, role");
        Set("SetInset", ["Node n", "double pad"], "n, pad");
        // Fwd leaves a trailing blank line; the class brace closes on it.
        b.Length -= System.Environment.NewLine.Length;
        b.AppendLine("}");
        b.AppendLine();
        b.AppendLine("/// <summary>The duck-typed enumerable behind Rows(): no IEnumerable,");
        b.AppendLine("/// so LINQ never appears on a collection at record time.</summary>");
        b.AppendLine($"readonly struct {rec}RowSeq");
        b.AppendLine("{");
        b.AppendLine($"    readonly RecordCollection<{rec}> c;");
        b.AppendLine();
        b.AppendLine($"    internal {rec}RowSeq(RecordCollection<{rec}> c) => this.c = c;");
        b.AppendLine();
        b.AppendLine($"    public {rec}RowEnumerator GetEnumerator() => new {rec}RowEnumerator(c);");
        b.AppendLine("}");
        b.AppendLine();
        b.AppendLine($"sealed class {rec}RowEnumerator : System.IDisposable");
        b.AppendLine("{");
        b.AppendLine("    int state;");
        b.AppendLine("    System.Action close;");
        b.AppendLine($"    readonly RecordCollection<{rec}> c;");
        b.AppendLine();
        b.AppendLine($"    internal {rec}RowEnumerator(RecordCollection<{rec}> c) => this.c = c;");
        b.AppendLine();
        b.AppendLine($"    public {rec}Row Current {{ get; private set; }}");
        b.AppendLine();
        b.AppendLine("    public bool MoveNext()");
        b.AppendLine("    {");
        b.AppendLine("        if (state != 0)");
        b.AppendLine("            return false;");
        b.AppendLine("        state = 1;");
        b.AppendLine("        var tx = KayaApp.Ambient?.CurrentTx");
        b.AppendLine("            ?? throw new System.InvalidOperationException(");
        b.AppendLine("                \"kaya: Rows() iterates at record time, inside a transaction\");");
        b.AppendLine("        var (t, done) = tx.BeginRowTrace(c.Collection);");
        b.AppendLine("        close = done;");
        b.AppendLine($"        Current = new {rec}Row(t);");
        b.AppendLine("        return true;");
        b.AppendLine("    }");
        b.AppendLine();
        b.AppendLine("    public void Dispose()");
        b.AppendLine("    {");
        b.AppendLine("        close?.Invoke();");
        b.AppendLine("        close = null;");
        b.AppendLine("    }");
        b.AppendLine("}");
        b.AppendLine();
        b.AppendLine($"sealed class {rec}KayaPatch");
        b.AppendLine("{");
        b.AppendLine($"    readonly RecordPatch<{rec}> p;");
        b.AppendLine();
        b.AppendLine($"    internal {rec}KayaPatch(RecordPatch<{rec}> p) => this.p = p;");
        foreach (var f in fields)
        {
            b.AppendLine();
            b.AppendLine($"    public {rec}KayaPatch {f.name}({f.type} v)");
            b.AppendLine("    {");
            b.AppendLine($"        p.Set({rec}Kaya.{f.name}, v);");
            b.AppendLine("        return this;");
            b.AppendLine("    }");
        }
        b.AppendLine("}");
        return b.ToString();
    }

    // Write only on change: regeneration is idempotent AND
    // mtime-stable, so a gen run never invalidates a concurrent build
    // reading the checked-in file.
    static void WriteIfChanged(string path, string content)
    {
        if (!File.Exists(path) || File.ReadAllText(path) != content)
            File.WriteAllText(path, content);
    }

    static string Lower(string s) => char.ToLowerInvariant(s[0]) + s.Substring(1);
}
